// ATOM2_W08 · Roteador de respostas do WhatsApp (Fluxo do Funil v1.0 §4; scripts de 09/10/2026).
// Classificação determinística por regras (auditável, sem IA): o que não for claro vai para o Thiago (Ambígua).
// Qualquer resposta encerra a cadência. Opt-out/sem interesse/agora não → negócio perdido com o motivo nativo.
// REGRA ABSOLUTA: nenhum preço antes da proposta. Pergunta de preço recebe RESPOSTA_SEM_PRECO (aprovada 09/10/2026);
// os scripts "Quanto custa?" e "Oferta de site" (que citam R$ 3.000) NÃO são usados por este roteador.
// Número desconhecido → lead receptivo: negócio no funil Atendimento Receptivo + registro r_<telefone> (sem resposta automática).
// SIMULACAO (padrão): resposta gravada como simulada; Pipedrive só é alterado para registros c_teste_*.
const API = 'https://api.pipedrive.com/v1';
const NOOP = { method: 'GET', url: API + '/users/me', body: {} };

// --- trava de preço e termos proibidos (bloco canônico de lib_guarda_preco.js) ---
// <guarda> — bloco canônico: copiado idêntico para W05, W05b, W07 e W08 por n8n/tools/sync_guarda.js (teste confere).
// Fronteiras Unicode: \b do JavaScript não trata "é", "à" etc. como letra.
const I = '(?<![\\p{L}\\p{N}])', F = '(?![\\p{L}\\p{N}])';
const rx = (corpo) => new RegExp(I + corpo + F, 'iu');
const EXTENSO = '(um|uma|dois|duas|tr[eê]s|quatro|cinco|seis|sete|oito|nove|dez|onze|doze|treze|quatorze|catorze|quinze|dezesseis|dezessete|dezoito|dezenove|vinte|trinta|quarenta|cinquenta|sessenta|setenta|oitenta|noventa|cem|cento|duzentos|duzentas|trezentos|trezentas|quatrocentos|quinhentos|seiscentos|setecentos|oitocentos|novecentos)';
const PRECO_RX = [
  /(R|US|U)?\s*[$＄]\s*\d/i,                                                                   // R$ 3.000, R $3000, US$ 500, $500
  rx('\\d{1,3}([.\\s]\\d{3})+([.,]\\d{2})?'),                                                 // 3.000 / 14.000,00 / 1 500,00
  rx('\\d+([.,]\\d+)?\\s*(mil|reais|k)'),                                                     // 3 mil, 900 reais, 3k
  rx(EXTENSO + '(\\s+e\\s+' + EXTENSO + ')*\\s+(mil|reais)'),                                 // três mil, dois mil e quinhentos
  rx('\\d+,\\d{2}'), rx('\\d+\\.\\d{2}'),                                                     // 500,00 / 500.00
  rx('\\d+([.,]\\d+)?\\s*(/\\s*m[eê]s|por m[eê]s|mensais|ao m[eê]s|/\\s*ano|por ano)'),       // 1500/mês, 990 mensais
  rx('\\d+\\s*x\\s*(de\\s*)?(R\\$\\s*)?\\d+'),                                                 // 12x 300, 2x de 750
  rx('(valor|custo|taxa|or[cç]amento|ticket|plano|investimento)\\s*(:|mensal|anual|de|é|e|fica|sai|total|inicial)?\\s*(R\\$\\s*)?\\d+'), // Valor: 1500, orçamento de 1500
  rx('(?<!(oportunidades|resultados|dados|casos|problemas|ganhos|melhorias|clientes|pacientes|n[uú]meros|exemplos|situa[cç][oõ]es|pessoas|avalia[cç][oõ]es|depoimentos|evid[eê]ncias|mudan[cç]as|benef[ií]cios)\\s)reais'),
  rx('pre[cç]os?'),
  rx('valor(es)?\\s+(de|do|da|para|é|e|fica|sai|total|mensal)'),
  rx('investimento\\s+(de|é|e|fica|sai|total|inicial|mensal)'),
  rx('(mensalidade|parcelas?|parcelado|entrada de|setup de|desconto|à vista|a vista|boleto|pix)'),
  rx('(custa|custo de|cobramos|sai por|fica por|a partir de)')
];
// Promessas e alegações proibidas (handoff §8; scripts de 09/10). "Ninguém pode garantir isso" (script ChatGPT) passa.
const PROIBIDOS = [/primeira posi[cç][aã]o/i, /topo do google/i, /garant(imos|ido|idos|ida|idas|o\b|ia de)/i, /posi[cç][aã]o\s*\d/i, /\b\d+\s*(visitas|clientes|pacientes) (por|ao) m[eê]s/i, /preju[ií]zo/i, /queda de vendas/i, /perdendo (clientes|pacientes|vendas)/i, /cliente oculto/i, /chatgpt (indicou|citou|recomendou)/i];
const bloqueios = (t) => [...PRECO_RX.filter((r) => r.test(String(t || ''))).map(() => 'preço antes da proposta'), ...PROIBIDOS.filter((r) => r.test(String(t || ''))).map((r) => 'termo proibido ' + r.source)];
// </guarda>
const RESPOSTA_SEM_PRECO = 'O investimento depende do que faz sentido para a [Empresa], e ele vem na proposta, depois de entendermos o cenário. Para eu já preparar algo certeiro: o que você mais quer melhorar hoje?';

// --- classificação (ordem importa: a primeira regra que casar vence) ---
const sem = (s) => String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/\s+/g, ' ').trim();
const NEG = /(^|[^a-z])(nao|nem|nunca)([^a-z]|$)/;
const REGRAS = [
  // Opt-out só com pedido claro ("só vou sair agora" e "agenda bloqueada" não são opt-out).
  ['OPT_OUT', 0.95, /(^(pare|parar|sair|stop|chega)[.! ]*$|(pare|para|parem|parar) de (me |nos )?(mandar|enviar|chamar|mensagem)|(quero|me) (sair|descadastrar)|sair da (sua )?lista|descadastr\w*|remov\w+ (meu|o|esse) (numero|contato)|tira(r)? (meu|o|esse) (numero|contato)|nao (me )?(mande|envie|chame|contate|procure|mandem|enviem) mais|nao quero (mais )?receber|(vou|vamos) (te |lhe )?(bloquear|denunciar)|me bloque\w*|denunci\w+|(^|[^a-z])spam([^a-z]|$)|lgpd)/],
  ['SEM_INTERESSE', 0.9, /(nao (tenho|temos) interesse|sem interesse|nao (me )?interessa|nao quero|nao preciso|nao precisamos|nao, obrigad|dispenso|nao estamos interessad)/],
  ['AGORA_NAO', 0.85, /(agora nao|no momento nao|nao (e|eh) o momento|mais (pra|para) frente|outro momento|proximo ano|ano que vem|depois (a gente|eu) (ve|vejo|falo)|sem tempo agora|nao agora)/],
  ['PRECO', 0.95, /(quanto (custa|fica|sai|e|eh|cobra|voces cobram)|qual (o |e o )?(valor|preco|investimento|custo)|preco|valores|orcamento|tabela de|esta caro|ta caro|muito caro|como conseguem esse preco|forma de pagamento|parcela)/],
  ['PROPOSTA', 0.9, /((mand|envi)\w* (uma |a )?proposta|quero (uma |a )?proposta|faz (uma |a )?proposta)/],
  ['CHATGPT', 0.85, /(chat ?gpt|garant\w* (aparecer|que aparece|estar))/],
  ['AGENCIA', 0.85, /(ja (tenho|temos) (uma )?agencia|ja (tenho|temos) (quem|alguem|empresa|um profissional) (que )?(cuid|fa[cz])|nossa agencia|trabalh\w+ com (uma )?agencia)/],
  ['SITE_BOM', 0.8, /((meu|nosso|o) site (ja )?(e|eh|esta|ta) (bom|otimo|ok|novo)|site (e|eh) novo)/],
  ['ATENDIMENTO', 0.8, /(melhorar (o |meu |nosso )?atendimento|atendimento (esta|ta|e) (ruim|lento|fraco)|nao (conseguimos|consigo) responder)/],
  ['EMAIL', 0.85, /((por|pelo|no) e-?mail|manda (no|pro|para o) e-?mail|[\w.+-]+@[\w-]+\.[\w.]+)/],
  ['INTERESSE', 0.9, /(tenho interesse|temos interesse|me interess|interessad|vamos conversar|podemos conversar|quero (saber|entender|conhecer) mais|pode (me )?ligar|qual horario|agend\w+ (uma )?(reuniao|conversa|call)|bora)/],
  ['PODE_ENVIAR', 0.9, /^(sim|pode|claro|ok|okay|beleza|blz|manda|mande|envia|envie|pode (sim|enviar|mandar)|quero ver|quero|por favor|pode ser|manda ai|envia ai|manda sim|pode mandar sim)\b|(pode (enviar|mandar)|manda (ai|sim|o diagnostico)|envia (ai|o diagnostico)|quero ver|gostaria de ver|pode compartilhar)/],
  ['ENCAMINHAMENTO', 0.8, /(fal\w+ com|(o|a) responsavel|quem cuida (e|eh)|vou (te )?(passar|encaminhar)|encaminh\w+ para|e com (o|a) (dr|dra|doutor|doutora)|o contato (dele|dela) e|\(?\d{2}\)?\s?9?\d{4}-?\d{4})/],
  ['IDENTIDADE', 0.8, /(quem (e|eh|fala|esta falando)|de onde (e|eh|voces sao)|como (conseguiu|pegou|achou) (meu|esse) (numero|contato)|que empresa)/]
];
// Pessoa indicada pela recepção: "Dra. Ana", "fala com a Bruna", "o responsável é o Pedro". Telefone, se houver.
function extrairPessoa(texto) {
  const t = String(texto || '');
  let m = t.match(/\b([Dd]r|[Dd]ra|[Dd]outor|[Dd]outora)\.?\s+([A-ZÀ-Ý][a-zà-ÿ]+)/);
  if (m) return (/^(dra|doutora)$/i.test(m[1]) ? 'Dra. ' : 'Dr. ') + m[2];
  m = t.match(/(?:fal\w*|fale|com|para|pra)\s+(?:o|a)\s+([A-ZÀ-Ý][a-zà-ÿ]{2,})/) || t.match(/(?:respons[aá]vel|quem cuida)\s+(?:é|e)\s+(?:o\s+|a\s+)?([A-ZÀ-Ý][a-zà-ÿ]{2,})/);
  return m ? m[1].charAt(0).toUpperCase() + m[1].slice(1) : '';
}
const telefoneDe = (texto) => { const m = String(texto || '').match(/\(?\d{2}\)?\s?9?\d{4}[-\s]?\d{4}/); return m ? m[0] : ''; };
function classificar(texto) {
  const t = sem(texto);
  if (!t) return { intencao: 'AMBIGUA', confianca: 0, regra: 'vazio' };
  // Recepção indicando o responsável vem antes de "pode enviar" ("pode mandar que eu passo pra Dra. Ana").
  if (!REGRAS[0][2].test(t) && !REGRAS[1][2].test(t) && (extrairPessoa(texto) || (telefoneDe(texto) && /(fal|liga|contato|whats|numero|passo|encaminh)/.test(t))) && /(fal|respons|cuida|passo|passar|encaminh|com (o|a) |pra (o|a) |para (o|a) |contato|liga|dr|dra|doutor)/.test(t)) return { intencao: 'ENCAMINHAMENTO', confianca: 0.85, regra: 'pessoa indicada' };
  if (/^(nao|n|nao obrigad\w*|no)[.!]*$/.test(t)) return { intencao: 'SEM_INTERESSE', confianca: 0.7, regra: 'nao isolado' };
  for (const [intencao, confianca, r] of REGRAS) {
    if (!r.test(t)) continue;
    // "não pode enviar", "não tenho interesse em conversar": aceitação negada não conta como aceitação.
    if (['PODE_ENVIAR', 'INTERESSE'].includes(intencao) && NEG.test(t)) continue;
    return { intencao, confianca, regra: r.source.slice(0, 60) };
  }
  return { intencao: 'AMBIGUA', confianca: 0.3, regra: 'nenhuma regra' };
}

// --- respostas (Biblioteca de scripts; [Nome] sai quando não há nome) ---
const RESPOSTAS = {
  OPT_OUT: 'Entendido, [Nome]. Obrigado pelo retorno. Não vou insistir.',
  SEM_INTERESSE: 'Entendido, [Nome]. Obrigado pelo retorno. Não vou insistir.',
  AGORA_NAO: 'Sem problema! Vou encerrar o acompanhamento.\nQuando fizer sentido, estou à disposição.',
  PRECO: RESPOSTA_SEM_PRECO,
  PROPOSTA: 'Claro! Me confirme o objetivo, o escopo e o prazo.\nAssim envio uma proposta precisa.',
  CHATGPT: 'Ninguém pode garantir isso. Trabalhamos SEO/GEO com fundamentos técnicos e conteúdo preparado para mecanismos de busca e IA.',
  AGENCIA: 'Ótimo! A análise pode complementar o trabalho atual.\nQuer ver os pontos que encontramos?',
  SITE_BOM: 'Ótimo! Nossa sugestão é pontual: [achado].\nQuer ver como melhorar esse ponto?',
  ATENDIMENTO: 'Hoje sua equipe consegue responder todos os contatos com rapidez?\nPodemos avaliar os dados do atendimento e mostrar oportunidades reais.',
  EMAIL: 'Combinado. Qual e-mail corporativo devo usar para enviar a análise?',
  INTERESSE: 'Excelente! Posso te mostrar as oportunidades e possíveis soluções em 15 minutos.\nQual horário é melhor para você?',
  ESTA_CARO: 'Entendo. O que pesa mais: investimento, prazo ou dúvida sobre o resultado esperado?',
  PRECISO_PENSAR: 'Claro! O que falta esclarecer para você decidir com segurança?',
  ACEITE: 'Excelente! Vou confirmar o escopo e encaminhar o contrato pela Autentique, conforme combinado.',
  PODE_ENVIAR: 'Perfeito! Aqui está o diagnóstico: [link].\nO que é prioridade hoje: mais contatos, agendamentos ou melhorar o atendimento?'
};
// Intenção → opção do campo "ATOM · Intenção da resposta" e motivo de perda nativo.
const OPCAO = { PODE_ENVIAR: 'PODE_ENVIAR', PRECO: 'QUANTO_CUSTA', INTERESSE: 'TENHO_INTERESSE', AGENCIA: 'JA_TENHO_AGENCIA', PROPOSTA: 'MANDE_PROPOSTA', AGORA_NAO: 'AGORA_NAO', SEM_INTERESSE: 'SEM_INTERESSE', OPT_OUT: 'OPT_OUT' };
// Depois da proposta (F9/F10/IN_PROPOSTA/IN_NEGOCIACAO): scripts "Está caro", "Preciso pensar" e "Cliente aceitou".
const POS_PROPOSTA = [['ESTA_CARO', /(caro|salgado|puxado|acima do (meu |nosso )?orcamento|nao cabe)/], ['PRECISO_PENSAR', /(preciso pensar|vou pensar|vou avaliar|deixa eu ver|vou analisar|preciso ver com|falar com (meu|minha) (socio|socia|esposa|marido))/], ['ACEITE', /(fechado|fechamos|aceito|aceitamos|pode fazer|vamos fechar|bora fechar|vamos seguir|pode seguir|topo|manda o contrato)/]];
function classificarPosProposta(texto) {
  const t = sem(texto);
  if (NEG.test(t)) return null;
  const r = POS_PROPOSTA.find(([, x]) => x.test(t));
  return r ? r[0] : null;
}
const PERDA = { OPT_OUT: 'Opt-out', SEM_INTERESSE: 'Sem interesse', AGORA_NAO: 'Agora não (sem recontato)' };
const TAREFA = {
  PODE_ENVIAR: 'Enviar o diagnóstico e qualificar (P1–P3)', PRECO: 'Lead perguntou preço: qualificar (preço só na proposta)', PROPOSTA: 'Lead pediu proposta: confirmar objetivo, escopo e prazo',
  INTERESSE: 'Agendar reunião de 15 min', AGENCIA: 'Lead já tem agência: mostrar os pontos', SITE_BOM: 'Lead acha o site bom: mostrar o achado', CHATGPT: 'Lead perguntou de ChatGPT/garantia',
  ATENDIMENTO: 'Lead quer melhorar o atendimento: avaliar dados', EMAIL: 'Lead pediu por e-mail: pegar o e-mail e enviar', ENCAMINHAMENTO: 'Recepção indicou o responsável: registrar nome e abordar o decisor',
  IDENTIDADE: 'Lead perguntou quem somos: responder pessoalmente', AMBIGUA: 'Resposta ambígua: ler e responder',
  ESTA_CARO: 'Proposta: lead achou caro (entender o que pesa)', PRECISO_PENSAR: 'Proposta: lead vai pensar (esclarecer dúvidas)', ACEITE: 'Lead aceitou pelo WhatsApp: marcar ganho e formalizar'
};
function preencher(modelo, nome, empresa, achado, link) {
  let t = modelo.replace('[Empresa]', empresa || 'sua empresa');
  if (achado) t = t.replace('[achado]', achado);
  if (link) t = t.replace('[link]', link);
  if (nome) return t.replace('[Nome]', nome);
  t = t.replace(', [Nome]', '').replace('[Nome], ', '');
  return t.charAt(0).toUpperCase() + t.slice(1);
}

// --- entrada: WhatsApp Cloud API ou formato simples { telefone, texto, wa_message_id, recebido_em } ---
function normalizarEntrada(body) {
  const b = body || {};
  const out = [];
  for (const en of b.entry || []) for (const ch of en.changes || []) for (const m of (ch.value && ch.value.messages) || []) {
    out.push({ telefone: String(m.from || ''), texto: (m.text && m.text.body) || (m.button && m.button.text) || (m.interactive && JSON.stringify(m.interactive)) || '', wa_message_id: m.id, recebido_em: m.timestamp ? new Date(Number(m.timestamp) * 1000).toISOString() : null, tipo: m.type || 'text' });
  }
  if (!out.length && (b.telefone || b.from)) out.push({ telefone: String(b.telefone || b.from), texto: String(b.texto || b.text || ''), wa_message_id: b.wa_message_id || b.id || null, recebido_em: b.recebido_em || null, tipo: 'text' });
  return out.filter((m) => m.telefone);
}
// Chave de telefone: só dígitos, sem 55, sem o 9 extra do celular → DDD + 8 dígitos.
function chaveTel(t) {
  let d = String(t || '').replace(/\D/g, '');
  if (d.length >= 12 && d.startsWith('55')) d = d.slice(2);
  if (d.length === 11 && d[2] === '9') d = d.slice(0, 2) + d.slice(3);
  return d.length === 10 ? d : null;
}

function hash(x) { let h = 0x811c9dc5; for (let i = 0; i < x.length; i++) { h ^= x.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }
// Dias úteis (mesma regra do W07): usado para agendar a trilha pós-diagnóstico.
const FERIADOS = ['2026-01-01', '2026-02-16', '2026-02-17', '2026-04-03', '2026-04-21', '2026-05-01', '2026-06-04', '2026-09-07', '2026-10-12', '2026-11-02', '2026-11-15', '2026-11-20', '2026-12-25',
  '2027-01-01', '2027-02-08', '2027-02-09', '2027-03-26', '2027-04-21', '2027-05-01', '2027-05-27', '2027-09-07', '2027-10-12', '2027-11-02', '2027-11-15', '2027-11-20', '2027-12-25'];
const diaSP = (d) => new Date(new Date(d).getTime() - 3 * 3600 * 1000).toISOString().slice(0, 10);
const util = (dia) => { const w = new Date(dia + 'T12:00:00Z').getUTCDay(); return w !== 0 && w !== 6 && !FERIADOS.includes(dia); };
function somarDiasUteis(agora, n) {
  let dia = diaSP(agora), c = 0;
  while (c < n) { const d = new Date(dia + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + 1); dia = d.toISOString().slice(0, 10); if (util(dia)) c++; }
  return dia + 'T12:00:00.000Z';
}

const cfgMapa = (rows) => {
  const m = {};
  for (const r of rows || []) if (r && r.chave) m[r.chave] = String(r.valor ?? '');
  const modos = (rows || []).filter((r) => r && r.chave === 'MODO_EXECUCAO').map((r) => String(r.valor).trim().toUpperCase());
  m.MODO_EXECUCAO = modos.length && modos.every((x) => x === 'PRODUCAO') ? 'PRODUCAO' : 'SIMULACAO';
  return m;
};

// Decide o que fazer com UMA mensagem recebida. Devolve { entrada, resposta?, cadencia?, empresa?, pd: [planos], evento, tarefa? }.
// pd: planos HTTP da fase 1 (deal); a fase 2 (nota + atividade) precisa do id do negócio → planoFase2().
function decidir(m, ctx) {
  const { empresas, cadencias, auditorias, achados, cfgRows, mensagens, agora } = ctx;
  const cfg = cfgMapa(cfgRows);
  const quando = agora || new Date().toISOString();
  // Sem wa_message_id (formato simples), a identidade vem do conteúdo: webhook repetido não duplica entrada nem resposta.
  const inId = 'in_' + (m.wa_message_id || chaveTel(m.telefone) + '_' + hash(String(m.texto || '') + '|' + String(m.recebido_em || '')));
  if ((mensagens || []).some((x) => x && x.msg_id === inId)) return null; // já processada (webhook repetido)
  const k = chaveTel(m.telefone);
  const cands = (empresas || []).filter((e) => e && k && chaveTel(e.telefone) === k);
  const e = cands.find((x) => x.pipedrive_deal_id) || cands[0] || null;
  const cl = classificar(m.texto);
  const teste = !!e && String(e.company_id).startsWith('c_teste_');
  const real = cfg.MODO_EXECUCAO === 'PRODUCAO' || teste;
  const f = (c) => cfg['PD2_FIELD_' + c];
  const opt = (c, s) => cfg['PD2_OPT_' + c + '_' + s];
  const entrada = { msg_id: inId, company_id: e ? e.company_id : 'r_' + (k || 'sem_numero'), deal_id: e && e.pipedrive_deal_id ? String(e.pipedrive_deal_id) : '', direcao: 'entrada', canal: 'whatsapp_n2', telefone: m.telefone, passo: '', texto: String(m.texto || '').slice(0, 4000), intencao: cl.intencao, status: 'recebida', motivo: 'regra: ' + cl.regra + ' (confiança ' + cl.confianca + ')', modo: cfg.MODO_EXECUCAO + (teste ? '_TESTE' : ''), wa_message_id: m.wa_message_id || '', criado_em: m.recebido_em || quando };
  const ev = (tipo, motivo, dados) => ({ event_id: 'e_w08_' + inId + '_' + tipo.toLowerCase(), correlation_id: entrada.deal_id ? 'deal_' + entrada.deal_id : entrada.company_id, company_id: entrada.company_id, workflow: 'ATOM2_W08', tipo, motivo, dados: JSON.stringify(dados || {}), ocorrido_em: quando });

  // 1) Número desconhecido → lead receptivo (funil Atendimento Receptivo, etapa Novo lead). Sem resposta automática.
  if (!e) {
    if (!k) return { entrada: { ...entrada, status: 'descartada', motivo: 'telefone inválido' }, pd: [{ ...NOOP }], evento: ev('ENTRADA_INVALIDA', 'telefone inválido') };
    const empresaNova = { company_id: entrada.company_id, nome: 'Contato WhatsApp +' + String(m.telefone).replace(/\D/g, ''), telefone: String(m.telefone).replace(/\D/g, ''), fluxo: 'receptivo', status: 'novo', funil_etapa: 'IN_NOVO', status_motivo: 'Lead receptivo pelo WhatsApp', owner: 'Thiago', opt_out: cl.intencao === 'OPT_OUT', lote_id: 'RECEPTIVO', criado_em: quando, atualizado_em: quando };
    const body = { title: empresaNova.nome + ' — Receptivo', pipeline_id: Number(cfg.PD2_PIPE_IN_ID), stage_id: Number(cfg.PD2_STAGE_IN_NOVO_ID), status: 'open', visible_to: 3 };
